from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v25r2, v22r2
from .modals import SynchronizeWithActivePartitionModal


class Software(v25r2.Software):

    def __init__(self, driver, download_checker):
        super(Software, self).__init__(driver, download_checker)
        self._software_update = SoftwareUpdatePage(driver, download_checker)
        self._beam_set_realization_software = BeamSetRealizationSoftwarePage(driver, download_checker)


class SoftwareUpdatePage(v22r2.software.SoftwareUpdatePage):

    def __init__(self, driver, download_checker):
        super(SoftwareUpdatePage, self).__init__(driver, download_checker)
        self._view_panel = SoftwareUpdatePageViewPanel(driver, download_checker)


class SoftwareUpdatePageViewPanel(v22r2.software.SoftwareUpdatePageViewPanel):

    def synchronize(self, with_health_check, timeout):
        self.click_enabled_element_after_visible((By.XPATH, self._SYNCHRONIZE_BUTTON), timeout)

        synchronize_with_active = SynchronizeWithActivePartitionModal(self.driver)
        synchronize_with_active.wait_until_synchronize_modal_appear(timeout)
        synchronize_with_active.health_check(with_health_check, timeout)
        synchronize_with_active.synchronize(timeout)
        return synchronize_with_active.wait_until_synchronize_completed(timeout)


class BeamSetRealizationSoftwarePage(v25r2.software.BeamSetRealizationSoftwarePage):

    def __init__(self, driver, download_checker):
        super(BeamSetRealizationSoftwarePage, self).__init__(driver, download_checker)
        self._view_panel = BeamSetRealizationSoftwarePageViewPanel(driver, download_checker)


class BeamSetRealizationSoftwarePageViewPanel(v25r2.software.BeamSetRealizationSoftwarePageViewPanel):

    _DELETE_BUTTON_XPATH = "//*[@class='bsr-remove-button']//button[.//span[text()='Delete']]"
    _CHECKBOX_XPATH = "//*[contains(@class, 'bsr-table')]//tbody//tr[./td[text()='{}']]//p-checkbox"
